+def impairment_bundle(executable: Path) -> dict[str, str]:
+    files = (executable, *(executable.parent / name for name in
+             ("WinDivert.dll", "WinDivert64.sys", "config.txt")))
+    if any(not path.is_file() for path in files):
+        raise RuntimeError("impairment executable/driver/config bundle is incomplete")
+    return {path.name: sha256_file(path) for path in files}
+
