+def require_impairment_preflight(executable: Path | None, profile: str,
+                                 proof_path: Path | None) -> dict[str, Any]:
+    """Fail before deployment unless the exact helper has demonstrated effects.
+
+    A live helper, recognized-looking switch or an administrator token is not a
+    capability measurement. Proof captures are sealed separately from gameplay.
+    """
+    if profile not in PROFILE_ARGUMENTS:
+        raise RuntimeError(f"unsupported impairment profile: {profile}")
+    if executable is None:
+        raise RuntimeError("impairment preflight requires an executable")
+    bundle = impairment_bundle(executable.resolve())
+    if proof_path is None:
+        raise RuntimeError("impairment requires a sealed controlled-traffic capability proof (--impairment-proof)")
+    proof = json.loads(proof_path.read_text(encoding="utf-8"))
+    if (proof.get("schema_version") != 1 or proof.get("bundle") != bundle
+            or proof.get("profile") != profile
+            or proof.get("arguments") != list(PROFILE_ARGUMENTS[profile])):
+        raise RuntimeError("impairment capability proof does not bind this tool/profile")
+    captures = proof.get("captures", [])
+    if not captures or any(not Path(row["path"]).is_file()
+            or sha256_file(Path(row["path"])) != row.get("sha256") for row in captures):
+        raise RuntimeError("impairment controlled-traffic captures are missing or stale")
+    observations = proof.get("observations", {})
+    if (observations.get("baseline_packets", 0) <= 0
+            or observations.get("affected_packets", 0) <= 0
+            or observations.get("profile_effect_measured") is not True
+            or proof.get("cleanup_complete") is not True):
+        raise RuntimeError("impairment has no measured controlled-traffic effect/cleanup")
+    if not _is_administrator():
+        raise RuntimeError("impairment requires an administrator runner before game launch")
+    return proof
+
